begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
insert into auth.users(id) values(md5('effort_a')::uuid),(md5('effort_b')::uuid);
insert into profiles(id,display_name) values(md5('effort_a')::uuid,'A'),(md5('effort_b')::uuid,'B');
insert into account_preferences(owner_id) values(md5('effort_a')::uuid),(md5('effort_b')::uuid);
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('effort_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.effort_session',start_ad_hoc_workout()::text,true);
select set_config('body_test.effort_item',edit_workout(current_setting('body_test.effort_session')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select set_config('body_test.effort_set',(select id::text from workout_sets where workout_exercise_id=current_setting('body_test.effort_item')::uuid order by position limit 1),true);
select ok((select bool_and(effort_scale is null and effort_value is null and not performed_to_failure and status='pending') from workout_sets where workout_exercise_id=current_setting('body_test.effort_item')::uuid),'new automatic rows do not invent effort/failure');
select is((select preferred_effort_scale from account_preferences where owner_id=auth.uid()),'rpe','new account default effort input');
update account_preferences set preferred_effort_scale='rir' where owner_id=auth.uid();
select is((select preferred_effort_scale from account_preferences where owner_id=auth.uid()),'rir','preference persists independently of load unit');
select is((select display_weight_unit from account_preferences where owner_id=auth.uid()),'lb','effort preference never changes load unit');
create function pg_temp.save_effort(e jsonb,typ text default 'working') returns void language sql security invoker as $$
 select public.log_workout_set(current_setting('body_test.effort_item')::uuid,current_setting('body_test.effort_set')::uuid,'save',(select revision from public.workout_sets where id=current_setting('body_test.effort_set')::uuid),gen_random_uuid(),5,22.68,typ,'external',true,null,50,'lb',e);
$$;
reset role;
update workout_sets set prescribed_effort_scale='rir',prescribed_effort_value=2,prescribed_to_failure=true where id=current_setting('body_test.effort_set')::uuid;
set local role authenticated;
select throws_ok($$update workout_sets set prescribed_effort_value=1 where id=current_setting('body_test.effort_set')::uuid$$,'42501',null,'clients cannot rewrite prescribed effort snapshots');
select lives_ok($$select pg_temp.save_effort(null)$$,'standard working set with no effort remains valid');
select ok((select effort_scale is null and effort_value is null and not performed_to_failure from workout_sets where id=current_setting('body_test.effort_set')::uuid),'omitted new effort is null/false');
select lives_ok($$select pg_temp.save_effort('{"scale":"rpe","value":9.5,"failure":false}')$$,'RPE halves accepted');
select is((select effort_value from workout_sets where id=current_setting('body_test.effort_set')::uuid),9.5::numeric,'exact original RPE stored');
select lives_ok($$select pg_temp.save_effort('{"scale":"rpe","value":10,"failure":false}')$$,'RPE 10 does not imply failure');
select ok((select not performed_to_failure from workout_sets where id=current_setting('body_test.effort_set')::uuid),'maximal reported RPE does not set failure');
select lives_ok($$select pg_temp.save_effort('{"scale":"rir","value":1,"failure":false}')$$,'actual RIR differs from prescribed target');
select ok((select prescribed_effort_value=2 and effort_value=1 and prescribed_to_failure and not performed_to_failure from workout_sets where id=current_setting('body_test.effort_set')::uuid),'planned and actual effort/failure stay separate');
select lives_ok($$select pg_temp.save_effort('{"scale":"rir","value":0,"failure":false}')$$,'zero RIR does not imply failure');
select ok((select not performed_to_failure and effort_scale='rir' and effort_value=0 from workout_sets where id=current_setting('body_test.effort_set')::uuid),'RIR scale and zero retained');
select lives_ok($$select pg_temp.save_effort('{"scale":null,"value":null,"failure":true}')$$,'failure without effort accepted');
select ok((select effort_scale is null and effort_value is null and performed_to_failure and set_type='working' from workout_sets where id=current_setting('body_test.effort_set')::uuid),'failure never fills or converts effort/type');
select lives_ok($$select pg_temp.save_effort('{"scale":"rpe","value":8,"failure":true}','drop')$$,'drop to failure with RPE accepted');
select ok((select set_type='drop' and performed_to_failure and effort_value=8 from workout_sets where id=current_setting('body_test.effort_set')::uuid),'drop classification preserved');
select lives_ok($$select pg_temp.save_effort('{"scale":"rir","value":5,"failure":true}','rest_pause')$$,'rest-pause to failure with 5+ RIR accepted independently');
select ok((select set_type='rest_pause' and performed_to_failure and effort_scale='rir' and effort_value=5 from workout_sets where id=current_setting('body_test.effort_set')::uuid),'reported independent fields not reconciled by inference');
select throws_ok($$select pg_temp.save_effort('{"scale":"rpe","value":8.1,"failure":false}')$$,'22023',null,'invalid RPE rejected');
select throws_ok($$select pg_temp.save_effort('{"scale":"rir","value":6,"failure":false}')$$,'22023',null,'invalid RIR rejected');
select throws_ok($$select pg_temp.save_effort('{"scale":"rir","value":0,"failure":true}','warm_up')$$,'22023',null,'warm-up failure rejected without replacing set type');
select throws_ok($$select pg_temp.save_effort('{"scale":"rpe","value":null,"failure":false}')$$,'22023',null,'scale without value rejected');
select throws_ok($$select pg_temp.save_effort('{"scale":null,"value":null,"failure":false,"owner":"x"}')$$,'22023',null,'unknown effort payload fields rejected');
select set_config('body_test.effort_time',(select last_activity_at::text from workout_sessions where id=current_setting('body_test.effort_session')::uuid),true);
select throws_ok($$select public.log_workout_set(current_setting('body_test.effort_item')::uuid,current_setting('body_test.effort_set')::uuid,'save',0,gen_random_uuid(),5,22.68,'working','external',true,null,50,'lb','{"scale":"rpe","value":9,"failure":false}')$$,'40001',null,'stale effort mutation rejected by CAS');
select is((select last_activity_at::text from workout_sessions where id=current_setting('body_test.effort_session')::uuid),current_setting('body_test.effort_time'),'failed effort write does not extend activity');
select lives_ok($$select public.log_workout_set(current_setting('body_test.effort_item')::uuid,current_setting('body_test.effort_set')::uuid,'save',(select revision from workout_sets where id=current_setting('body_test.effort_set')::uuid),gen_random_uuid(),5,22.68,'rest_pause','external',true,null,50,'lb')$$,'old named/positional call shape preserves reported effort');
select ok((select effort_scale='rir' and effort_value=5 and performed_to_failure and actual_weight_kg=22.68 and entered_weight=50 from workout_sets where id=current_setting('body_test.effort_set')::uuid),'legacy compatible update retains effort and exact load');
select lives_ok($$select pg_temp.save_effort('{"scale":"rpe","value":9,"failure":true}')$$,'effort save after conflict can succeed with latest revision');
select ok((select last_activity_at>current_setting('body_test.effort_time')::timestamptz from workout_sessions where id=current_setting('body_test.effort_session')::uuid),'successful effort save atomically counts as meaningful activity');
select set_config('request.jwt.claims',json_build_object('sub',md5('effort_b')::uuid,'role','authenticated')::text,true);
select throws_ok($$select pg_temp.save_effort('{"scale":"rpe","value":8,"failure":false}')$$,'42501',null,'other user cannot save effort');
select is((select count(*)::int from workout_sets where id=current_setting('body_test.effort_set')::uuid),0,'other user cannot inspect effort');
with changed as(update account_preferences set preferred_effort_scale='rpe' where owner_id=md5('effort_a')::uuid returning *) select is(count(*)::int,0,'other user preference update hidden') from changed;
select set_config('request.jwt.claims',json_build_object('sub',md5('effort_a')::uuid,'role','authenticated')::text,true);
select is((select preferred_effort_scale from account_preferences where owner_id=auth.uid()),'rir','foreign attempt leaves preference unchanged');
select lives_ok($$select end_workout(current_setting('body_test.effort_session')::uuid,'completed')$$,'finish preserves actual effort');
select is((select max(value) from record_metrics((select id from exercises where slug='barbell_bench_press')) where metric='heaviest'),22.68::numeric,'PR truth unaffected by effort/failure');
select ok((select effort_scale='rpe' and effort_value=9 and performed_to_failure from workout_sets where id=current_setting('body_test.effort_set')::uuid),'historical values retained');
select throws_ok($$update workout_sets set effort_value=8 where id=current_setting('body_test.effort_set')::uuid$$,'23514',null,'closed historical effort immutable');
select set_config('body_test.next_effort',start_ad_hoc_workout()::text,true);
select set_config('body_test.next_item',edit_workout(current_setting('body_test.next_effort')::uuid,'add',(select id from exercises where slug='barbell_bench_press'))::text,true);
select ok((select bool_and(effort_scale is null and effort_value is null and not performed_to_failure and actual_reps is null) from workout_sets where workout_exercise_id=current_setting('body_test.next_item')::uuid),'smart defaults copy prescription suggestions, never actual previous effort/failure');
select * from finish();rollback;
